<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/public-site.php';
$context=public_site_fallback_context();try{$context=public_site_context(app_pdo());}catch(Throwable $e){error_log('Public gelato load failed: '.$e->getMessage());}
$settings=$context['settings'];$section=public_site_section($context['menuSections'],'gelato');$items=$section&&is_array($section['items']??null)?$section['items']:[];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0b09"><title>Gelato | <?=app_escape((string)$settings['restaurant_name'])?></title><link rel="stylesheet" href="assets/css/site.css?v=20260914-2"><link rel="stylesheet" href="assets/css/page-headers.css?v=20260914-1"></head><body class="page-gelato"><?php public_site_render_header($settings,'gelato');?><main class="page-main"><section class="page-hero"><div class="shell"><div class="eyebrow">Gelato</div><h1>The Perfect Finish.</h1><p><?=$section&&trim((string)($section['intro']??''))!==''?app_escape((string)$section['intro']):'The current gelato lineup is pulled directly from the restaurant menu database.'?></p></div></section><section class="section"><div class="shell gelato-page-grid"><div><div class="eyebrow">Current Selection</div><h2><?=$section?app_escape((string)$section['name']):'Gelato Menu'?></h2><?php if($items):?><div class="gelato-list"><?php foreach($items as $item):?><article class="gelato-item"><div><h3><?=app_escape((string)$item['name'])?></h3><?php if(trim((string)$item['description'])!==''):?><p><?=app_escape((string)$item['description'])?></p><?php endif;?></div><?php $price=public_site_price($item);?><div class="menu-price"><?=$price!==''?app_escape($price):''?></div></article><?php endforeach;?></div><?php else:?><div class="empty-state">No active gelato items are currently published.</div><?php endif;?></div><div class="gelato-image"><img src="<?=app_escape(public_site_asset('gelato.jpg'))?>" alt="Stonefellows gelato"></div></div></section></main><?php public_site_render_footer($settings);?><script src="assets/js/site.js?v=20260914"></script><script src="assets/js/public-shell.js?v=20260915-1"></script>
</body></html>
